    numbers.sort()
    n = len(numbers)
    mean = sum(numbers) / n

    if n % 2 == 1:
        median = numbers[n // 2]
    else:
        median = (numbers[n // 2 - 1] + numbers[n // 2]) / 2

    return round(mean, 2), round(median, 2)
