def compute_mode(nums: list[int]) -> list[int]:
    if not nums:
        return []

    frequency = Counter(nums)
    max_freq = max(frequency.values())
    mode = [num for num, freq in frequency.items() if freq == max_freq]

    return sorted(mode)
