def count_subsequence_matches(text: str, sub: str) -> int:
    m, n = len(text), len(sub)

    # Create a 2D DP array with (m+1) x (n+1) dimensions
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: An empty subsequence is a subsequence of any prefix of text
    for i in range(m + 1):
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text[i - 1] == sub[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[m][n]
