def count_subsequence_matches(text: str, sub: str) -> int:
    m, n = len(text), len(sub)
    if n == 0:
        return 1
    if m == 0:
        return 0

    # dp[i][j] will store the count of ways to form sub[0:j] from text[0:i]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # An empty subsequence can be formed in one way from any prefix of text
    for i in range(m + 1):
        dp[i][0] = 1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text[i - 1] == sub[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[m][n]
