def count_subsequence_matches(text: str, sub: str) -> int:
    m, n = len(text), len(sub)

    # dp[i][j] will store the count of ways to form sub[0..j] from text[0..i]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # An empty subsequence can be formed in exactly one way from any prefix of text
    for i in range(m + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # If the current character of text matches the current character of sub
            if text[i - 1] == sub[j - 1]:
                # Include the current character of text and exclude it
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                # Exclude the current character of text
                dp[i][j] = dp[i - 1][j]

    # The answer is the number of ways to form the entire sub from the entire text
    return dp[m][n]

