from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    # Create adjacency list and in-degree array
    adj_list = defaultdict(list)
    in_degree = [0] * n

    for a, b in pairs:
        if a == b:
            return []  # Cycle detected
        adj_list[a].append(b)
        in_degree[b] += 1

    # Initialize the queue with nodes having zero in-degree
    queue = deque([i for i in range(n) if in_degree[i] == 0])
    result = []

    while queue:
        # Choose the smallest element lexicographically
        current = min(queue)
        queue.remove(current)
        result.append(current)

        for neighbor in adj_list[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If result contains all nodes, it's a valid topological sort
    if len(result) == n:
        return result
    else:
        return []  # Cycle detected

