import operator
import re

def evaluate_expression(expr: str) -> int:
    # Tokenize the expression
    tokens = re.findall(r'\d+|\+|-|\*|/|\^|\(|\)', expr.replace(' ', ''))

    # Operator precedence and associativity
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    right_associative = {'^'}

    # Helper function to apply an operator to two operands
    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left // right)
        elif op == '^':
            values.append(left ** right)

    # Helper function to determine if we should apply an operator
    def should_apply(operators, op):
        if not operators:
            return False
        top = operators[-1]
        if (top in right_associative and precedence[top] <= precedence[op]) or (top not in right_associative and precedence[top] < precedence[op]):
            return True
        return False

    # Shunting Yard algorithm to convert to postfix
    def to_postfix(tokens):
        operators = []
        postfix = []
        for token in tokens:
            if token.isdigit():
                postfix.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    postfix.append(operators.pop())
                operators.pop()  # Pop the '('
            else:
                while should_apply(operators, token):
                    postfix.append(operators.pop())
                operators.append(token)
        while operators:
            postfix.append(operators.pop())
        return postfix

    # Evaluate the postfix expression
    def evaluate_postfix(postfix):
        values = []
        for token in postfix:
            if isinstance(token, int):
                values.append(token)
            else:
                apply_operator(operators, values)
        return values[0]

    postfix = to_postfix(tokens)
    return evaluate_postfix(postfix)
