        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        if op == '^':
            return 3
        return 0

    def greater_precedence(op1: str, op2: str) -> bool:
        return precedence(op1) > precedence(op2) or (precedence(op1) == precedence(op2) and op1 != '^')

