import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    token_pattern = re.compile(r'\s*([0-9]+(\.[0-9]+)?)|([a-zA-Z_][a-zA-Z0-9_]*)|([+\-*/<>=(),]|[<>]=?)')

    pos = 0
    while pos < len(source):
        match = token_pattern.match(source, pos)
        if match:
            kind = None
            text = match.group(0)
            if match.group(1):
                kind = "NUMBER"
            elif match.group(3):
                kind = "NAME"
            elif match.group(4) or match.group(5):
                kind = "OP"
            tokens.append((kind, text))
            pos = match.end()
        else:
            raise ValueError(f"Unexpected character at position {pos}")

