def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []

    for op, key, *value in operations:
        if op == "get":
            if key in cache:
                results.append(cache[key])
                cache.move_to_end(key)
            else:
                results.append(None)
        elif op == "put":
            if capacity > 0:
                if key in cache:
                    del cache[key]
                elif len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = value[0]

    return results, list(cache.keys())
