def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        if instruction.isdigit():
            stack.append(int(instruction))
        elif instruction == '+':
            if len(stack) < 2:
                raise ValueError("Not enough operands for +")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif instruction == '-':
            if len(stack) < 2:
                raise ValueError("Not enough operands for -")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif instruction == '*':
            if len(stack) < 2:
                raise ValueError("Not enough operands for *")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif instruction == '/':
            if len(stack) < 2:
                raise ValueError("Not enough operands for /")
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            stack.append(a // b)
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
    return stack
