import re

def identifier_to_snake(name: str) -> str:
    # Split the name by underscores and hyphens
    pieces = re.split(r'[_-]', name)

    # Further split pieces by transitions between lower-case, upper-case, and digits
    words = []
    for piece in pieces:
        words.extend(re.findall(r'[a-z]+|[A-Z][a-z]*|[A-Z]+(?=[A-Z][a-z])|\d+', piece))

    # Join the words with underscores and convert to lower case
    return '_'.join(words).lower()

