from collections import defaultdict, deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = defaultdict(deque)
    waiting_list = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
            while waiting[item]:
                order_quantity = waiting[item][0]
                if stock[item] >= order_quantity:
                    stock[item] -= order_quantity
                    waiting[item].popleft()
                    waiting_list.remove((item, order_quantity))
                else:
                    break
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting[item].append(quantity)
                waiting_list.append((item, quantity))

    return dict(stock), waiting_list
