            if account in final_balances and amount > 0 and account not in frozen_accounts:
                final_balances[account] += amount
            else:
                failed.append(i)

        elif op[0] == 'withdraw':
            account, amount = op[1], op[2]
            if account in final_balances and amount > 0 and account not in frozen_accounts and final_balances[account] >= amount:
                final_balances[account] -= amount
            else:
                failed.append(i)

        elif op[0] == 'transfer':
            source, target, amount = op[1], op[2], op[3]
            if source in final_balances and target in final_balances and amount > 0 and source not in frozen_accounts and target not in frozen_accounts and source != target and final_balances[source] >= amount + 2:
                final_balances[source] -= amount + 2
                final_balances[target] += amount
            else:
                failed.append(i)

        elif op[0] == 'freeze':
            account = op[1]
            if account in final_balances:
                frozen_accounts.add(account)

        elif op[0] == 'unfreeze':
            account = op[1]
            if account in final_balances:
                frozen_accounts.discard(account)

        else:
            failed.append(i)

    return final_balances, failed
