def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0

        if kind == 'receive':
            stock[item] += quantity
            # Process waiting orders for this item
            while waiting and stock[item] >= waiting[0][1]:
                _, order_quantity = waiting.pop(0)
                stock[item] -= order_quantity

        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Sort waiting orders by the order they were received
    waiting.sort(key=lambda x: events.index((x[0], x[1])))

    return stock, waiting
