def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if stack:
                stack.pop()
            else:
                return None
        elif parts[0] == 'DUP':
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif parts[0] == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
            else:
                return None
        elif parts[0] == 'SUB':
            if len(stack) >= 2:
                stack.append(-stack.pop() + stack.pop())
            else:
                return None
        elif parts[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
            else:
                return None
        elif parts[0] == 'DIV':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                if b == 0:
                    return None
                stack.append(a // b)
            else:
                return None
        elif parts[0] == 'MOD':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                if b == 0:
                    return None
                stack.append(a % b)
            else:
                return None
    return stack
