def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c.lower() not in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for c in number.replace('-', '')):
        raise ValueError("Invalid input number or base")

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    is_negative = number.startswith('-')
    number = number.lstrip('-').lower()

    # Convert from from_base to base 10
    base_10_value = 0
    for digit in number:
        base_10_value = base_10_value * from_base + '0123456789abcdefghijklmnopqrstuvwxyz'.index(digit)

    if is_negative:
        base_10_value = -base_10_value

    # Convert from base 10 to to_base
    if base_10_value == 0:
        return '0'

    digits = []
    is_negative = base_10_value < 0
    base_10_value = abs(base_10_value)

    while base_10_value > 0:
        digits.append('0123456789abcdefghijklmnopqrstuvwxyz'[base_10_value % to_base])
        base_10_value //= to_base

    if is_negative:
        digits.append('-')

    return ''.join(reversed(digits))
