    base_10_number = 0
    for char in number:
        base_10_number = base_10_number * from_base + digits.index(char.lower())

    # Handle negative numbers
    if is_negative:
        base_10_number = -base_10_number

    # Convert from base 10 to the target base
    if base_10_number == 0:
        return "0"

    result = []
    is_negative_result = base_10_number < 0
    base_10_number = abs(base_10_number)

    while base_10_number > 0:
        result.append(digits[base_10_number % to_base])
        base_10_number //= to_base

    if is_negative_result:
        result.append('-')

    return ''.join(reversed(result))

