from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    # BFS to find the shortest path with at most one break
    queue = deque([(0, 0, 0, False)])  # (x, y, steps, has_broken)
    visited = set((0, 0, False))

    while queue:
        x, y, steps, has_broken = queue.popleft()

        if (x, y) == (rows - 1, cols - 1):
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny):
                if not has_broken and (nx, ny, True) not in visited:
                    visited.add((nx, ny, True))
                    queue.append((nx, ny, steps + 1, True))
                elif has_broken and (nx, ny, False) not in visited:
                    visited.add((nx, ny, False))
                    queue.append((nx, ny, steps + 1, False))

    return -1
