import re
from typing import List, Dict

def parse_jobs(text: str) -> List[Dict]:
    jobs = []
    job_pattern = re.compile(r'### (.+?)\n\n(.*?)\n\n', re.DOTALL)
    for job_match in job_pattern.findall(text):
        job_title = job_match[0].strip()
        job_details = job_match[1].strip()

        details = {}
        detail_pattern = re.compile(r'(\w+):\s*(.+)')
        for detail_match in detail_pattern.findall(job_details):
            key = detail_match[0].strip()
            value = detail_match[1].strip()
            details[key] = value

        jobs.append({
            'title': job_title,
            **details
        })

    return jobs

