from typing import List, Union

def evaluate_expression(expression: str) -> float:
    def apply_operator(operators: List[str], values: List[Union[int, float]]) -> None:
        operator_func = {
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.truediv,
            '**': operator.pow
        }
        right = values.pop()
        left = values.pop()
        values.append(operator_func[operators.pop()](left, right))

    def greater_precedence(op1: str, op2: str) -> bool:
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
        return precedence[op1] > precedence[op2]

    def parse_number(token: str) -> Union[int, float]:
        if '.' in token:
            return float(token)
        return int(token)

    tokens = re.findall(r'\d+\.\d+|\d+|\S', expression)
    values: List[Union[int, float]] = []
    operators: List[str] = []

    for token in tokens:
        if token.isdigit() or '.' in token:
            values.append(parse_number(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        elif token in '+-*/**':
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], token)):
                apply_operator(operators, values)
            operators.append(token)
        else:
            raise ValueError(f"Invalid character: {token}")

    while operators:
        apply_operator(operators, values)

    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]
