import re
import operator
from typing import List, Union

def evaluate_expression(expression: str) -> float:
    def tokenize(s: str) -> List[Union[float, str]]:
        token_pattern = r'\s*([-+*/^()]|\d+(\.\d*)?|\.\d+)\s*'
        tokens = re.findall(token_pattern, s)
        if not tokens:
            raise ValueError("Invalid expression")
        return [float(t[0]) if t[0].replace('.', '', 1).isdigit() else t[0] for t in tokens]

    def parse(tokens: List[Union[float, str]]) -> float:
        def parse_expression(index: int) -> (float, int):
            def parse_term(index: int) -> (float, int):
                def parse_factor(index: int) -> (float, int):
                    if tokens[index] == '(':
                        value, index = parse_expression(index + 1)
                        if tokens[index] != ')':
                            raise ValueError("Mismatched parentheses")
                        return value, index + 1
                    elif isinstance(tokens[index], float):
                        return tokens[index], index + 1
                    else:
                        raise ValueError("Invalid token")

                value, index = parse_factor(index)
                while index < len(tokens) and tokens[index] in ('*', '/'):
                    op = tokens[index]
                    right, index = parse_factor(index + 1)
                    value = value * right if op == '*' else value / right
                return value, index

            value, index = parse_term(index)
            while index < len(tokens) and tokens[index] in ('+', '-'):
                op = tokens[index]
                right, index = parse_term(index + 1)
                value = value + right if op == '+' else value - right
            return value, index

        value, index = parse_expression(0)
        if index != len(tokens):
            raise ValueError("Extra tokens at the end")
        return value

    tokens = tokenize(expression)
    return parse(tokens)
