import ast
import operator

def matches_filter(expression: str, record: dict) -> bool:
    # Define valid operators
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.BitXor: operator.xor,
        ast.USub: operator.neg,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.And: operator.and_,
        ast.Or: operator.or_,
        ast.Not: operator.not_,
    }

    # Define a node visitor to evaluate the expression
    class Evaluate(ast.NodeVisitor):
        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            return operators[type(node.op)](left, right)

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            return operators[type(node.op)](operand)

        def visit_Compare(self, node):
            left = self.visit(node.left)
            comparator = operators[type(node.ops[0])]
            right = self.visit(node.comparators[0])
            return comparator(left, right)

        def visit_Name(self, node):
            if node.id in record:
                return record[node.id]
            else:
                raise ValueError(f"Unknown variable: {node.id}")

        def visit_Constant(self, node):
            return node.value

        def visit_Num(self, node):
            return node.n

        def visit_Str(self, node):
            return node.s

        def visit_Expr(self, node):
            return self.visit(node.value)

        def visit_BoolOp(self, node):
            values = [self.visit(value) for value in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            elif isinstance(node.op, ast.Or):
                return any(values)

        def visit_Not(self, node):
            return not self.visit(node.operand)

    # Parse the expression
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression")

    # Evaluate the expression
    evaluator = Evaluate()
    try:
        result = evaluator.visit(tree)
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

    return result
