import math
from typing import Callable, Dict

def evaluate_formula(formula: str, x: float) -> float:
    # Define allowed functions and their implementations
    functions: Dict[str, Callable[[float], float]] = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Replace 'x' with the actual value in the formula
    formula = formula.replace('x', str(x))

    # Add spaces around operators and parentheses for easier parsing
    formula = formula.replace('(', ' ( ').replace(')', ' ) ')
    formula = formula.replace('+', ' + ').replace('-', ' - ')
    formula = formula.replace('*', ' * ').replace('/', ' / ')
    formula = formula.replace('**', ' ** ')

    # Tokenize the formula
    tokens = formula.split()

    # Evaluate the formula using a stack-based approach
    stack = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isnumeric() or (token[0] == '-' and token[1:].isnumeric()):
            stack.append(float(token))
        elif token in functions:
            if i + 1 >= len(tokens) or not tokens[i + 1].startswith('('):
                raise ValueError("Function call must be followed by parentheses")
            # Find the matching closing parenthesis
            open_paren_count = 1
            j = i + 2
            while j < len(tokens) and open_paren_count > 0:
                if tokens[j] == '(':
                    open_paren_count += 1
                elif tokens[j] == ')':
                    open_paren_count -= 1
                j += 1
            if open_paren_count != 0:
                raise ValueError("Mismatched parentheses in function call")
            # Evaluate the argument
            arg = evaluate_formula(' '.join(tokens[i + 2:j - 1]), x)
            # Apply the function
            result = functions[token](arg)
            stack.append(result)
            i = j - 1
        elif token == '(':
            # Find the matching closing parenthesis
            open_paren_count = 1
            j = i + 1
            while j < len(tokens) and open_paren_count > 0:
                if tokens[j] == '(':
                    open_paren_count += 1
                elif tokens[j] == ')':
                    open_paren_count -= 1
                j += 1
            if open_paren_count != 0:
                raise ValueError("Mismatched parentheses")
            # Evaluate the expression inside the parentheses
            result = evaluate_formula(' '.join(tokens[i + 1:j - 1]), x)
            stack.append(result)
            i = j - 1
        elif token in ('+', '-', '*', '/', '**'):
            # Apply the operator
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                stack.append(left + right)
            elif token == '-':
                stack.append(left - right)
            elif token == '*':
                stack.append(left * right)
            elif token == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                stack.append(left / right)
            elif token == '**':
                stack.append(left ** right)
        else:
            raise ValueError(f"Invalid token: {token}")
        i += 1

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]

