def is_local_redirect(target: str, host: str) -> bool:
    # Check for invalid characters
    if any(ord(c) < 32 or ord(c) == 127 or c in '\\ ' for c in target):
        return False

    # Check for site-relative path
    if target.startswith('/') and (len(target) == 1 or target[1] != '/'):
        return True

    # Check for absolute URL
    parsed_url = urlparse(target)
    if parsed_url.scheme in ('http', 'https'):
        # Compare hostnames case-insensitively
        return parsed_url.hostname.lower() == host.lower()

