def count_items(xml_text: str) -> int:
    try:
        root = ET.fromstring(xml_text)
        return count_items_recursive(root)
    except ET.ParseError:
        return 0

def count_items_recursive(element):
    count = 0
    if element.tag == 'item':
        count += 1
    for child in element:
        count += count_items_recursive(child)
    return count

