def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from collections import deque

    n = len(coins)
    if target == 0:
        return 0

    # Initialize a queue for BFS
    queue = deque([(0, 0)])  # (current amount, current coin count)
    visited = set([0])

    while queue:
        current_amount, current_count = queue.popleft()

        for i in range(n):
            if current_amount + coins[i] <= target and limits[i] > 0:
                new_amount = current_amount + coins[i]
                new_count = current_count + 1

                if new_amount == target:
                    return new_count

                if new_amount not in visited:
                    visited.add(new_amount)
                    queue.append((new_amount, new_count))

                # Decrease the limit for the current coin
                limits[i] -= 1

    return -1

