def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    from collections import defaultdict
    from typing import List

    def dfs(node: int, parent: int, low: List[int], disc: List[int], time: int, bridges: List[tuple[int, int]]):
        nonlocal graph
        time += 1
        disc[node] = low[node] = time
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if disc[neighbor] == -1:
                dfs(neighbor, node, low, disc, time, bridges)
                low[node] = min(low[node], low[neighbor])
                if low[neighbor] > disc[node]:
                    bridges.append((min(node, neighbor), max(node, neighbor)))
            else:
                low[node] = min(low[node], disc[neighbor])

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    disc = [-1] * n
    low = [-1] * n
    bridges = []

    for i in range(n):
        if disc[i] == -1:
            dfs(i, -1, low, disc, 0, bridges)

    return sorted(bridges)
