from typing import List

def evaluate_expression(expr: str) -> int:
    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        operator = operators.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            values.append(left // right)
        elif operator == '^':
            values.append(int(left ** right))

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        if op == '^':
            return 3
        return 0

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2) or (precedence(op1) == precedence(op2) and op1 != '^')

    def evaluate(tokens):
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            elif token in "+-*/^":
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], token)):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '-':
                if i == 0 or tokens[i - 1] in "+-*/(":
                    values.append(0)
                    operators.append('-')
            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    # Remove spaces and split by tokens
    tokens = re.findall(r'\d+|\+|-|\*|/|\^|\(|\)', expr.replace(' ', ''))
    return evaluate(tokens)
