def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define operator precedence and associativity
    precedence = {'^': 4, '*': 3, '/': 3, '+': 2, '-': 2}
    right_associative = {'^'}

    def apply_operator(operators, values):
        right = operators.pop()
        right_val = values.pop()
        left_val = values.pop()
        if right == '+':
            values.append(left_val + right_val)
        elif right == '-':
            values.append(left_val - right_val)
        elif right == '*':
            values.append(left_val * right_val)
        elif right == '/':
            if right_val == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left_val // right_val)
        elif right == '^':
            values.append(left_val ** right_val)

    def greater_precedence(op1, op2):
        return precedence[op1] > precedence[op2] or (precedence[op1] == precedence[op2] and op2 in right_associative)

    def evaluate(tokens):
