def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    instruction_count = 0
    max_instructions = 1000

    while ip < len(program) and instruction_count < max_instructions:
        instruction = program[ip]
        parts = instruction.split()
        opcode = parts[0]

        if opcode == "PUSH":
            if len(parts) != 2:
                raise ValueError("Invalid PUSH instruction")
            try:
                stack.append(int(parts[1]))
            except ValueError:
                raise ValueError("Invalid integer in PUSH instruction")
        elif opcode == "POP":
            if len(stack) < 1:
                raise ValueError("Not enough values on the stack for POP")
            stack.pop()
        elif opcode == "DUP":
            if len(stack) < 1:
                raise ValueError("Not enough values on the stack for DUP")
            stack.append(stack[-1])
        elif opcode == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for ADD")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif opcode == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for SUB")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif opcode == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for MUL")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif opcode == "JMP":
            if len(parts) != 2:
                raise ValueError("Invalid JMP instruction")
            try:
                ip = int(parts[1])
                continue
            except ValueError:
                raise ValueError("Invalid integer in JMP instruction")
        elif opcode == "JZ":
            if len(parts) != 2:
                raise ValueError("Invalid JZ instruction")
            if len(stack) < 1:
