from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up
    start = None
    end = None

    # Find the start and end positions
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if not start or not end:
        return -1

    # BFS to find the minimum number of moves
    queue = deque([(start, 0)])  # (current position, number of moves)
    visited = set()
    visited.add(start)

    while queue:
        (r, c), moves = queue.popleft()

        if (r, c) == end:
            return moves

        for dr, dc in directions:
            nr, nc = r, c
            while 0 <= nr + dr < rows and 0 <= nc + dc < cols and grid[nr + dr][nc + dc] != '#':
                nr += dr
                nc += dc

            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append(((nr, nc), moves + 1))

    return -1
