def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    def multiply_matrices(a: list[list[int]], b: list[list[int]], mod: int) -> list[list[int]]:
        n = len(a)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def identity_matrix(n: int) -> list[list[int]]:
        return [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    n = len(matrix)
    result = identity_matrix(n)
    base = matrix

    while exp > 0:
        if exp % 2 == 1:
            result = multiply_matrices(result, base, mod)
        base = multiply_matrices(base, base, mod)
        exp //= 2

    return result
