def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def get_ring(r, c, size):
        ring = []
        for i in range(size):
            ring.append(matrix[r][c + i])
        for i in range(1, size - 1):
            ring.append(matrix[r + i][c + size - 1])
        for i in range(size):
            ring.append(matrix[r + size - 1][c + size - 1 - i])
        for i in range(1, size - 1):
            ring.append(matrix[r + size - 1 - i][c])
        return ring

    def set_ring(r, c, size, ring):
        index = 0
        for i in range(size):
            result[r][c + i] = ring[index]
            index += 1
        for i in range(1, size - 1):
            result[r + i][c + size - 1] = ring[index]
            index += 1
        for i in range(size):
            result[r + size - 1][c + size - 1 - i] = ring[index]
            index += 1
        for i in range(1, size - 1):
            result[r + size - 1 - i][c] = ring[index]
            index += 1

    for layer in range((n + 1) // 2):
        size = n - 2 * layer
        ring = get_ring(layer, layer, size)
        k_effective = k % (2 * (size - 1) + 2)
        ring = ring[-k_effective:] + ring[:-k_effective]
        set_ring(layer, layer, size, ring)

    return result
