            decoded.append(char * count)
    return ''.join(decoded)

def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter out invalid busy ranges
    busy = [(start, end) for start, end in busy if start < end]

    # Sort busy ranges by start time
    busy.sort()

    free_slots = []
    current_start = day_start

    for start, end in busy:
        if start > current_start:
            # Found a free slot
            if start - current_start >= min_len:
                free_slots.append((current_start, start))
        # Move to the end of the current busy range
        current_start = max(current_start, end)

    # Check for a free slot at the end of the day
    if day_end - current_start >= min_len:
        free_slots.append((current_start, day_end))

    return free_slots

def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order, maintaining original order for ties
    jobs.sort(key=lambda x: (-x[2], jobs.index(x)))

    # Initialize a list to keep track of scheduled jobs in each interval
    scheduled = []

    # Iterate over each job
    for name, deadline, profit in jobs:
        # Find the highest available interval that does not exceed the deadline
        for interval in range(deadline, 0, -1):
            if interval - 1 < len(scheduled) and scheduled[interval - 1] is not None:
                continue
            # Schedule the job in this interval
            if interval - 1 >= len(scheduled):
                scheduled.append(name)
            else:
                scheduled[interval - 1] = name
            break

    # Filter out any None values (unused intervals) and return the list of scheduled job names
    return [job for job in scheduled if job is not None]

