from collections import defaultdict

def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    table = defaultdict(lambda: {'points': 0, 'goals_scored': 0, 'goals_conceded': 0})

    for home, away, home_goals, away_goals in results:
        table[home]['goals_scored'] += home_goals
        table[home]['goals_conceded'] += away_goals
        table[away]['goals_scored'] += away_goals
        table[away]['goals_conceded'] += home_goals

        if home_goals > away_goals:
            table[home]['points'] += 3
        elif home_goals < away_goals:
            table[away]['points'] += 3
        else:
            table[home]['points'] += 1
            table[away]['points'] += 1

    return sorted(
        [(team, data['points'], data['goals_scored'] - data['goals_conceded'], data['goals_scored'])
         for team, data in table.items()],
        key=lambda x: (-x[1], -x[2], -x[3], x[0])
    )
