def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_valid(row, col, queens):
        for r, c in queens:
            if c == col or r + c == row + col or r - c == row - col:
                return False
        return True

    def backtrack(row, queens):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if (row, col) not in blocked and is_valid(row, col, queens):
                count += backtrack(row + 1, queens + [(row, col)])
        return count

    return backtrack(0, [])
