                pending_item, pending_quantity = waiting[i]
                if pending_item == item and stock[item] >= pending_quantity:
                    stock[item] -= pending_quantity
                    waiting.pop(i)
                else:
                    i += 1

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
            else:
