def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    pending_orders = {}

    for kind, item, quantity in events:
        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity

            # Process pending orders for this item
            while pending_orders.get(item, []):
                order_quantity = pending_orders[item][0]
                if stock[item] >= order_quantity:
                    stock[item] -= order_quantity
                    pending_orders[item].pop(0)
                else:
                    break

        elif kind == 'order':
            if item not in stock:
                stock[item] = 0

            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                if item not in pending_orders:
                    pending_orders[item] = []
                pending_orders[item].append(quantity)
                waiting.append((item, quantity))

    # Collect all items with inventory 0
    for item in pending_orders:
        if item not in stock:
            stock[item] = 0

    return stock, waiting
