            if account not in final_balances or amount <= 0 or account in frozen_accounts or final_balances[account] < amount:
                failed.append(i)
                continue
            final_balances[account] -= amount

        elif op[0] == 'transfer':
            source, target, amount = op[1], op[2], op[3]
            if source not in final_balances or target not in final_balances or amount <= 0 or source in frozen_accounts or target in frozen_accounts or source == target or final_balances[source] < amount + 2:
                failed.append(i)
                continue
            final_balances[source] -= amount + 2
            final_balances[target] += amount

        elif op[0] == 'freeze':
            account = op[1]
            if account not in final_balances:
                failed.append(i)
                continue
            frozen_accounts.add(account)

        elif op[0] == 'unfreeze':
            account = op[1]
            if account not in final_balances:
                failed.append(i)
                continue
            frozen_accounts.discard(account)

    return final_balances, failed
