def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits(n: int) -> int:
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    total_count = 0
    for i in range(lo, hi + 1):
        total_count += count_set_bits(i)

    return total_count
