def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000
    instructions_executed = 0

    while ip < len(program) and instructions_executed < max_instructions:
        instructions_executed += 1
        instruction = program[ip].split()
        op = instruction[0]

        if op == "PUSH":
            stack.append(int(instruction[1]))
        elif op == "POP":
            if len(stack) == 0:
                return None
            stack.pop()
        elif op == "DUP":
            if len(stack) == 0:
                return None
            stack.append(stack[-1])
        elif op == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "ADD":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif op == "SUB":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == "MUL":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif op == "JMP":
            ip = int(instruction[1])
            continue
        elif op == "JZ":
            if len(stack) == 0:
                return None
            if stack.pop() == 0:
                ip = int(instruction[1])
                continue
        else:
            return None

        ip += 1

    if instructions_executed >= max_instructions:
        return None

    return stack
