def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    new_grid = [row[:] for row in grid]

    def collapse(r, c):
        if new_grid[r][c] >= 4:
            new_grid[r][c] -= 4
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_grid[nr][nc] += 1

    stable = False
    while not stable:
        stable = True
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    collapse(r, c)
                    stable = False

    return new_grid
