        if new_grid[r][c] >= 4:
            new_grid[r][c] -= 4
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_grid[nr][nc] += 1

    stable = False
    while not stable:
        stable = True
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    stable = False
                    topple(r, c)

    return new_grid

