def evaluate_expression(expression: str) -> float:
    # Define operator precedence and functions
    op_precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
    op_functions = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow
    }

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '/' and right == 0:
            raise ZeroDivisionError("Division by zero")
        values.append(op_functions[op](left, right))

    def greater_precedence(op1, op2):
        return op_precedence[op1] > op_precedence[op2]

    def parse_expression(tokens):
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
                values.append(float(token))
            elif token in op_functions:
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], token)):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    # Tokenize the expression
    token_pattern = r'\d+\.\d+|\d+|[-+*/()]'
    tokens = re.findall(token_pattern, expression.replace(' ', ''))

    if not tokens:
        raise ValueError("Invalid expression")

    # Parse and evaluate the expression
    return parse_expression(tokens)
