from typing import List, Tuple

def evaluate_expression(expression: str) -> float:
    # Define operator precedence and functions
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv, '**': operator.pow}

    def apply_operator(operators: List[str], values: List[float]) -> None:
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        values.append(ops[op](left, right))

    def greater_precedence(op1: str, op2: str) -> bool:
        return precedence[op1] > precedence[op2] or (precedence[op1] == precedence[op2] and op1 in ('*', '/', '**'))

    def parse_expression(tokens: List[str]) -> float:
        values = []
        operators = []

        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
                values.append(float(token))
            elif token.startswith('-') and token[1:].replace('.', '', 1).isdigit():
                values.append(float(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            elif token in ops:
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], token)):
                    apply_operator(operators, values)
                operators.append(token)
            else:
                raise ValueError(f"Invalid token: {token}")

            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    # Tokenize the input expression
    tokens = re.findall(r'\d+\.\d+|\d+|-?\d+\.\d+|-?\d+|[()+\-*/**]', expression.replace(' ', ''))

    if not tokens:
        raise ValueError("Invalid expression")

    # Evaluate the expression
    try:
        return parse_expression(tokens)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")

