def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    if target == 0:
        return 0

    n = len(coins)
    dp = [[float('inf')] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(target + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= coins[i - 1] and dp[i - 1][j - coins[i - 1]] != float('inf') and dp[i - 1][j - coins[i - 1]] + 1 <= limits[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - coins[i - 1]] + 1)

    return dp[n][target] if dp[n][target] != float('inf') else -1
