    pq = [(0, [start])]
    visited = set()

    while pq:
        cost, path = heappop(pq)
        node = path[-1]

        if node in visited:
            continue
        visited.add(node)

        if node == goal:
            return (cost, path)

        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                new_cost = cost + weight
                heappush(pq, (new_cost, new_path))

    return None

