def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # BFS to find the shortest paths
    queue = deque([(source, 1)])  # (current_node, path_count)
    visited = [False] * n
    visited[source] = True
    shortest_path_count = 0
    shortest_distance = float('inf')

    while queue:
        current, path_count = queue.popleft()

