            if path_count < shortest_distance:
                shortest_distance = path_count
                shortest_path_count = 1
            elif path_count == shortest_distance:
                shortest_path_count += 1
            continue

        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append((neighbor, path_count + 1))

