                val = parse_expression(tokens)
                tokens.pop(0)  # Remove ')'
                return val
            elif tokens[0] == '-':
                tokens.pop(0)
                return -parse_factor()
            else:
                val = int(tokens.pop(0))
                return val

        def parse_term() -> int:
