def evaluate_expression(expr: str) -> int:
    import re
    import operator
    from collections import deque

    # Tokenize the expression
    tokens = re.findall(r'\d+|\+|-|\*|/|\^|\(|\)', expr.replace(' ', ''))

    # Operator precedence and associativity
    precedence = {'^': 4, '*': 3, '/': 3, '+': 2, '-': 2}
    right_associative = {'^'}

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            values.append(int(left / right))
        elif op == '^':
            values.append(int(left ** right))

    def greater_precedence(op1, op2):
        return precedence[op1] > precedence[op2] or (precedence[op1] == precedence[op2] and op1 in right_associative)

    def evaluate(tokens):
        values = deque()
        operators = deque()

        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            else:  # Operator
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], token)):
                    apply_operator(operators, values)
                operators.append(token)

            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    return evaluate(tokens)
