def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    instruction_count = 0

    while ip < len(program) and instruction_count <= 1000:
        instruction = program[ip]
        parts = instruction.split()

        if parts[0] == "PUSH":
            if len(parts) != 2 or not parts[1].isdigit():
                raise ValueError
            stack.append(int(parts[1]))
        elif parts[0] == "POP":
            if len(stack) == 0:
                raise ValueError
            stack.pop()
        elif parts[0] == "DUP":
            if len(stack) == 0:
                raise ValueError
            stack.append(stack[-1])
        elif parts[0] == "SWAP":
            if len(stack) < 2:
                raise ValueError
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == "ADD":
            if len(stack) < 2:
                raise ValueError
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif parts[0] == "SUB":
            if len(stack) < 2:
                raise ValueError
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif parts[0] == "MUL":
            if len(stack) < 2:
                raise ValueError
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif parts[0] == "JMP":
            if len(parts) != 2 or not parts[1].isdigit():
                raise ValueError
            ip = int(parts[1])
            continue
        elif parts[0] == "JZ":
            if len(parts) != 2 or not parts[1].isdigit():
                raise ValueError
            if len(stack) == 0:
                raise ValueError
            if stack.pop() == 0:
                ip = int(parts[1])
                continue
        elif parts[0] == "HALT":
            break
        else:
            raise ValueError

        ip += 1
        instruction_count += 1

    if instruction_count > 1000:
        raise RuntimeError

    return stack
