from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the start and exit positions
    start = None
    exit_pos = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                exit_pos = (r, c)

    if not start or not exit_pos:
        return -1

    # BFS to find the minimum number of moves
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (r, c), moves = queue.popleft()

        for dr, dc in directions:
            nr, nc = r, c
            while 0 <= nr + dr < rows and 0 <= nc + dc < cols and grid[nr + dr][nc + dc] != '#':
                nr += dr
                nc += dc

            if (nr, nc) == exit_pos:
                return moves + 1

            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append(((nr, nc), moves + 1))

    return -1
