def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def rotate_ring(r, c, size):
        ring = []
        # Collect the ring elements
        for i in range(size):
            ring.append(matrix[r][c + i])
        for i in range(1, size):
            ring.append(matrix[r + i][c + size - 1])
        for i in range(size - 2, -1, -1):
            ring.append(matrix[r + size - 1][c + i])
        for i in range(size - 2, 0, -1):
            ring.append(matrix[r + i][c])

        # Rotate the ring
        k_effective = k % (4 * size - 4)
        ring = ring[-k_effective:] + ring[:-k_effective]

        # Place the rotated ring back
        index = 0
        for i in range(size):
            result[r][c + i] = ring[index]
            index += 1
        for i in range(1, size):
            result[r + i][c + size - 1] = ring[index]
            index += 1
        for i in range(size - 2, -1, -1):
            result[r + size - 1][c + i] = ring[index]
            index += 1
        for i in range(size - 2, 0, -1):
            result[r + i][c] = ring[index]
            index += 1

    # Rotate each ring
    for layer in range(n // 2):
        rotate_ring(layer, layer, n - 2 * layer)

    return result
