def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order, maintaining original order for ties
    jobs.sort(key=lambda x: (-x[2], jobs.index(x)))

    # Initialize a list to keep track of placed jobs in each slot
    slots = []

    for name, deadline, profit in jobs:
        # Find the highest-numbered slot that does not exceed the deadline
        for slot in range(deadline, 0, -1):
            if slot - 1 < len(slots) and slots[slot - 1] is None:
                slots[slot - 1] = name
                break
        else:
            # If no suitable slot is found, check if we need to extend the slots list
            if deadline > len(slots):
                slots.extend([None] * (deadline - len(slots)))
                slots[deadline - 1] = name

    # Filter out None values and return the list of placed job names
    return [job for job in slots if job is not None]
