def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order, maintaining original order for ties
    jobs.sort(key=lambda x: (-x[2], jobs.index(x)))

    # Initialize a list to keep track of scheduled slots
    scheduled_slots = []

    # Iterate over each job
    for name, deadline, profit in jobs:
        # Find the largest available slot that is less than or equal to the deadline
        for slot in range(deadline, 0, -1):
            if slot not in scheduled_slots:
                scheduled_slots.append(slot)
                break

    # Sort the scheduled slots in ascending order
    scheduled_slots.sort()

    # Map the slots back to job names
    slot_to_job = {slot: None for slot in scheduled_slots}
    for name, deadline, profit in jobs:
        for slot in range(deadline, 0, -1):
            if slot in scheduled_slots and slot_to_job[slot] is None:
                slot_to_job[slot] = name
                break

    # Create the result list with job names in the order of their slots
    result = [slot_to_job[slot] for slot in scheduled_slots]

    return result
