from itertools import permutations

def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    if not guests:
        return [[]]

    # Convert conflicts to a set of frozensets for faster lookup
    conflict_set = {frozenset(conflict) for conflict in conflicts}

    def is_valid(arrangement):
        for i in range(len(arrangement) - 1):
            if frozenset((arrangement[i], arrangement[i + 1])) in conflict_set:
                return False
        return True

    # Generate all permutations of guests
    all_permutations = permutations(guests)

    # Filter valid permutations
    valid_arrangements = [list(perm) for perm in all_permutations if is_valid(perm)]

    # Sort the valid arrangements lexicographically
    valid_arrangements.sort()

    return valid_arrangements
