def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    waiting_orders = {}

    for kind, item, quantity in events:
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            # Process waiting orders for this item
            while waiting_orders.get(item, []):
                order_quantity = waiting_orders[item][0]
                if stock[item] >= order_quantity:
                    stock[item] -= order_quantity
                    waiting.remove((item, order_quantity))
                    waiting_orders[item].pop(0)
                else:
                    break

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))
                if item in waiting_orders:
                    waiting_orders[item].append(quantity)
                else:
                    waiting_orders[item] = [quantity]

    # Remove items with 0 stock from the stock dictionary
    stock = {item: qty for item, qty in stock.items() if qty > 0}

    return stock, waiting
