def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or (number == '-' and from_base == 0):
        raise ValueError("Invalid input")

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"

    # Check for valid characters in the input number
    if any(char.lower() not in digits[:from_base] for char in number.replace('-', '')):
        raise ValueError("Invalid character in input number")

    # Handle negative numbers
    is_negative = number.startswith('-')
    if is_negative:
        number = number[1:]

    # Convert from from_base to base 10
    base_10_number = 0
    for char in number:
        base_10_number = base_10_number * from_base + digits.index(char.lower())

    # Handle zero case
    if base_10_number == 0:
        return '0'

    # Convert from base 10 to to_base
    result = []
    while base_10_number > 0:
        result.append(digits[base_10_number % to_base])
        base_10_number //= to_base

    # Add negative sign if necessary
    if is_negative:
        result.append('-')

    # Return the result in the correct order
    return ''.join(reversed(result))
