def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000
    instructions_executed = 0

    while ip < len(program) and instructions_executed < max_instructions:
        instructions_executed += 1
        instruction = program[ip]
        parts = instruction.split()

        if parts[0] == "PUSH":
            stack.append(int(parts[1]))
        elif parts[0] == "POP":
            if len(stack) > 0:
                stack.pop()
            else:
                return None
        elif parts[0] == "DUP":
            if len(stack) > 0:
                stack.append(stack[-1])
            else:
                return None
        elif parts[0] == "SWAP":
            if len(stack) > 1:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif parts[0] == "ADD":
            if len(stack) > 1:
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            else:
                return None
        elif parts[0] == "SUB":
            if len(stack) > 1:
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            else:
                return None
        elif parts[0] == "MUL":
            if len(stack) > 1:
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            else:
                return None
        elif parts[0] == "JMP":
