def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    new_grid = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    def topple(r, c):
        if new_grid[r][c] >= 4:
            new_grid[r][c] -= 4
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_grid[nr][nc] += 1

    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    topple(r, c)
                    changed = True

    return new_grid
