from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find the start and end positions
    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    # BFS to find the shortest path with at most one break
    queue = deque([(start[0], start[1], 0, False)])  # (row, col, steps, broke_wall)
    visited = set()
    visited.add((start[0], start[1], False))

    while queue:
        r, c, steps, broke_wall = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.':
                    if (nr, nc, broke_wall) not in visited:
                        visited.add((nr, nc, broke_wall))
                        queue.append((nr, nc, steps + 1, broke_wall))
                elif grid[nr][nc] == '#' and not broke_wall:
                    if (nr, nc, True) not in visited:
                        visited.add((nr, nc, True))
                        queue.append((nr, nc, steps + 1, True))

    return -1
