from typing import Callable, Dict

def evaluate_formula(formula: str, x: float) -> float:
    # Define allowed functions and operators
    allowed_functions: Dict[str, Callable] = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Define a safe eval function
    def safe_eval(expr: str, x: float) -> float:
        # Create a local scope with the allowed functions and the variable x
        local_scope = {**allowed_functions, 'x': x}
        try:
            # Evaluate the expression safely
            return eval(expr, {"__builtins__": None}, local_scope)
        except ZeroDivisionError:
            raise ZeroDivisionError("Division by zero is not allowed.")
        except Exception as e:
            raise ValueError(f"Invalid formula: {e}")

    # Evaluate the formula
    return safe_eval(formula, x)
