import math

def evaluate_formula(formula: str, x: float) -> float:
    # Define a dictionary to map function names to their implementations
    functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Define a class to handle the evaluation of the formula
    class Evaluator:
        def __init__(self, formula):
            self.tokens = self.tokenize(formula)
            self.index = 0

        def tokenize(self, formula):
            import re
            # Tokenize the formula using regex to match numbers, operators, and functions
            tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/()x]|sqrt|abs|sin|cos', formula)
            return tokens

        def parse(self):
            return self.expression()

        def expression(self):
            left = self.term()
            while self.index < len(self.tokens) and self.tokens[self.index] in ('+', '-'):
                op = self.tokens[self.index]
                self.index += 1
                right = self.term()
                if op == '+':
                    left += right
                elif op == '-':
                    left -= right
            return left

        def term(self):
            left = self.factor()
            while self.index < len(self.tokens) and self.tokens[self.index] in ('*', '/'):
                op = self.tokens[self.index]
                self.index += 1
                right = self.factor()
                if op == '*':
                    left *= right
                elif op == '/':
                    left /= right
            return left

        def factor(self):
            token = self.tokens[self.index]
            self.index += 1
            if token == '(':
                result = self.parse()
                if self.tokens[self.index] != ')':
                    raise ValueError("Mismatched parentheses")
                self.index += 1
                return result
            elif token == '-':
                return -self.factor()
            elif token == 'x':
                return x
            elif token in functions:
                if self.tokens[self.index] != '(':
                    raise ValueError("Expected '(' after function name")
                self.index += 1
                arg = self.parse()
                if self.tokens[self.index] != ')':
                    raise ValueError("Mismatched parentheses")
                self.index += 1
                return functions[token](arg)
            elif '.' in token or token.isdigit():
                return float(token)
            else:
                raise ValueError(f"Invalid token: {token}")

    # Create an instance of the Evaluator and parse the formula
    evaluator = Evaluator(formula)
    result = evaluator.parse()

    # If there are any remaining tokens, the formula is invalid
    if evaluator.index != len(evaluator.tokens):
        raise ValueError("Unexpected token at the end of the formula")

    return result
