        return False

    # Remove the https:// prefix
    url = url[8:]

    # Check for invalid characters
    if re.search(r'[\x00-\x20\x7F/ ]', url):
        return False

    # Split the URL into user info, host, and port
    if '@' in url:
        user_info, url = url.split('@', 1)
    else:
        user_info = ''

    if ':' in url:
        host, port = url.split(':', 1)
    else:
        host = url
        port = ''

    # Remove one trailing dot from the host
    if host.endswith('.'):
        host = host[:-1]

    # Check if the host is a valid DNS name
    if not re.match(r'^(?!localhost$)(?!.*\.localhost$)([a-zA-Z0-9-]+\.)+[a-zA-Z]+$', host, re.IGNORECASE):
